/bin/zsh -c "python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
from collections import Counter
class Check(HTMLParser):
    def __init__(self): super().__init__(); self.title=False; self.h1=False; self.title_text=[]; self.h1_text=[]; self.ids=[]; self.assets=[]; self.capture=None
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if 'id' in attrs: self.ids.append(attrs['id'])
        if tag=='title': self.capture='title'
        if tag=='h1': self.capture='h1'
        for key in ('src','href'):
            value=attrs.get(key,'')
            if value.startswith('./'): self.assets.append(value[2:])
    def handle_endtag(self, tag):
        if tag=='title' and self.capture=='title': self.capture=None
        if tag=='h1' and self.capture=='h1': self.capture=None
    def handle_data(self, data):
        if self.capture=='title': self.title_text.append(data)
        if self.capture=='h1': self.h1_text.append(data)
p=Check(); p.feed(Path('index.html').read_text())
assert ''.join(p.title_text).strip()=='GPT-6'
assert ''.join(p.h1_text).strip()=='GPT-6'
duplicates=[k for k,v in Counter(p.ids).items() if v>1]
missing=[name for name in p.assets if not Path(name).is_file()]
assert not duplicates, f'duplicate ids: {duplicates}'
assert not missing, f'missing local assets: {missing}'
print('index.html: title, h1, ids, and local assets ok')
PY"

